pub const StringContext = struct {
    strings_buf: []const u8,
    strings_lens: []const u32,

pub fn hash(self: StringContext, s: []const u8) u32 {
            _ = self.strings_buf;
            return @as(u32, @truncate(std.hash.Wyhash.hash(0, s)));
    }

pub fn eql(self: StringContext, fetch_key: []const u8, item_key: StringMapKey, item_i: usize) bool {
            return bun.strings.eqlLong(fetch_key, self.strings_buf[@intFromEnum(item_key)..][0..self.strings_lens[@as(usize, @intCast(item_i))]], true);
    }
};

pub const LocalNameToModuleName = struct {
    module_name: StringID,
    import_name: StringID,
    record_kinds_idx: usize,
    is_namespace: bool,
};

pub const ModuleInfo = struct {
    gpa: std.mem.Allocator,
    strings_map: std.ArrayHashMapUnmanaged(StringMapKey, void, void, true),
    strings_buf: std.ArrayListUnmanaged(u8),
    strings_lens: std.ArrayListUnmanaged(u32),
    requested_modules: std.AutoArrayHashMap(StringID, FetchParameters),
    buffer: std.ArrayListUnmanaged(StringID),
    record_kinds: std.ArrayListUnmanaged(RecordKind),
    flags: Flags,
    exported_names: std.AutoArrayHashMapUnmanaged(StringID, void),
    finalized: bool = false,
    _deserialized: ModuleInfoDeserialized,

pub fn asDeserialized(self: *ModuleInfo) *ModuleInfoDeserialized {
            _ = bun.assert(self.finalized);
            return (&self._deserialized);
    }

pub fn addVar(self: *ModuleInfo, name: StringID, kind: VarKind) !void {
            switch (kind) {
.declared => {
_ = try self.addDeclaredVariable(name);
},
.lexical => {
_ = try self.addLexicalVariable(name);
},
}
    }

pub fn _addRecord(self: *ModuleInfo, kind: RecordKind, data: []const StringID) !void {
            _ = bun.assert((!self.finalized));
            _ = bun.assert((data.len == ((kind.len()) catch unreachable)));
            _ = try self.record_kinds.append(self.gpa, kind);
            _ = try self.buffer.appendSlice(self.gpa, data);
    }

pub fn addDeclaredVariable(self: *ModuleInfo, id: StringID) !void {
            _ = try self._addRecord(.declared_variable, (&.{ id }));
    }

pub fn addLexicalVariable(self: *ModuleInfo, id: StringID) !void {
            _ = try self._addRecord(.lexical_variable, (&.{ id }));
    }

pub fn addImportInfoSingle(self: *ModuleInfo, module_name: StringID, import_name: StringID, local_name: StringID, only_used_as_type: bool) !void {
            _ = try self._addRecord((if (only_used_as_type) .import_info_single_type_script else .import_info_single), (&.{ module_name, import_name, local_name }));
    }

pub fn addImportInfoNamespace(self: *ModuleInfo, module_name: StringID, local_name: StringID) !void {
            _ = try self._addRecord(.import_info_namespace, (&.{ module_name, .star_namespace, local_name }));
    }

pub fn addExportInfoIndirect(self: *ModuleInfo, export_name: StringID, import_name: StringID, module_name: StringID) !void {
            if (try self._hasOrAddExportedName(export_name)) {
                return;
            }
            _ = try self._addRecord(.export_info_indirect, (&.{ export_name, import_name, module_name }));
    }

pub fn addExportInfoLocal(self: *ModuleInfo, export_name: StringID, local_name: StringID) !void {
            if (try self._hasOrAddExportedName(export_name)) {
                return;
            }
            _ = try self._addRecord(.export_info_local, (&.{ export_name, local_name, @enumFromInt(std.math.maxInt(u32)) }));
    }

pub fn addExportInfoNamespace(self: *ModuleInfo, export_name: StringID, module_name: StringID) !void {
            if (try self._hasOrAddExportedName(export_name)) {
                return;
            }
            _ = try self._addRecord(.export_info_namespace, (&.{ export_name, module_name }));
    }

pub fn addExportInfoStar(self: *ModuleInfo, module_name: StringID) !void {
            _ = try self._addRecord(.export_info_star, (&.{ module_name }));
    }

pub fn _hasOrAddExportedName(self: *ModuleInfo, name: StringID) !bool {
            if ((try self.exported_names.fetchPut(self.gpa, name, undefined) != null)) {
                return true;
            }
            return false;
    }

pub fn create(gpa: std.mem.Allocator, is_typescript: bool) !*ModuleInfo {
            const res = try gpa.create(ModuleInfo);
            res.* = ModuleInfo.init(gpa, is_typescript);
            return res;
    }

pub fn init(allocator: std.mem.Allocator, is_typescript: bool) ModuleInfo {
            return .{ .gpa = allocator, .strings_map = .{}, .strings_buf = .{}, .strings_lens = .{}, .exported_names = .{}, .requested_modules = std.AutoArrayHashMap(StringID, FetchParameters).init(allocator), .buffer = .empty, .record_kinds = .empty, .flags = .{ .contains_import_meta = false, .is_typescript = is_typescript }, ._deserialized = undefined };
    }

pub fn deinit(self: *ModuleInfo) void {
            _ = self.strings_map.deinit(self.gpa);
            _ = self.strings_buf.deinit(self.gpa);
            _ = self.strings_lens.deinit(self.gpa);
            _ = self.exported_names.deinit(self.gpa);
            _ = self.requested_modules.deinit();
            _ = self.buffer.deinit(self.gpa);
            _ = self.record_kinds.deinit(self.gpa);
    }

pub fn destroy(self: *ModuleInfo) void {
            const alloc = self.gpa;
            _ = self.deinit();
            _ = alloc.destroy(self);
    }

pub fn str(self: *ModuleInfo, value: []const u8) !StringID {
            _ = try self.strings_buf.ensureUnusedCapacity(self.gpa, value.len);
            _ = try self.strings_lens.ensureUnusedCapacity(self.gpa, 1);
            const gpres = try self.strings_map.getOrPutAdapted(self.gpa, value, StringContext{ .strings_buf = self.strings_buf.items, .strings_lens = self.strings_lens.items });
            if (gpres.found_existing) {
                return @enumFromInt(@as(u32, @truncate(gpres.index)));
            }
            gpres.key_ptr.* = @enumFromInt(@as(u32, @truncate(self.strings_buf.items.len)));
            gpres.value_ptr.* = undefined;
